DROP TABLE IF EXISTS `orders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `orders` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `invoiceID` varchar(255) NOT NULL,
  `entry_complete` varchar(255) DEFAULT NULL,
  `web_id` varchar(255) DEFAULT NULL,
  `user_id` varchar(255) DEFAULT NULL,
  `Payment` varchar(255) DEFAULT NULL,
  `customerNote` text DEFAULT NULL,
  `memo` varchar(255) DEFAULT NULL,
  `payment_type_id` int(11) DEFAULT NULL,
  `payment_id` varchar(255) DEFAULT NULL,
  `paymentAgentNumber` varchar(255) DEFAULT NULL,
  `courier_id` int(11) DEFAULT 26,
  `tracking_number` varchar(255) DEFAULT NULL,
  `shipped_at` timestamp NULL DEFAULT NULL,
  `warehouse_sent_at` timestamp NULL DEFAULT NULL,
  `steadfast_status` varchar(255) DEFAULT NULL,
  `steadfast_consignment_id` varchar(255) DEFAULT NULL,
  `steadfast_last_synced_at` timestamp NULL DEFAULT NULL,
  `steadfast_payload` longtext DEFAULT NULL,
  `city_id` int(11) DEFAULT NULL,
  `zone_id` int(11) DEFAULT NULL,
  `subTotal` int(11) NOT NULL,
  `profit` decimal(10,2) NOT NULL DEFAULT 0.00,
  `order_bonus` decimal(10,2) NOT NULL DEFAULT 0.00,
  `deliveryCharge` int(11) DEFAULT NULL,
  `discountCharge` int(11) DEFAULT NULL,
  `paymentAmount` int(11) DEFAULT NULL,
  `orderDate` date NOT NULL,
  `deliveryDate` date DEFAULT NULL,
  `completeDate` date DEFAULT NULL,
  `last_updated` date DEFAULT NULL,
  `status` varchar(255) NOT NULL DEFAULT 'Pending',
  `admin_id` int(11) NOT NULL,
  `store_id` int(11) NOT NULL,
  `trx_id` text DEFAULT NULL,
  `trackingLink` text DEFAULT NULL,
  `cancel_comment` text DEFAULT NULL,
  `transaction_id` text DEFAULT NULL,
  `data` text DEFAULT NULL,
  `cart` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=375 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

