--
-- Table structure for table `products`
--

DROP TABLE IF EXISTS `products`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `products` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `vendor_id` bigint(20) unsigned DEFAULT NULL,
  `vendor_approval_status` varchar(20) DEFAULT NULL,
  `allow_dropship` tinyint(1) NOT NULL DEFAULT 0,
  `selling_type` varchar(20) NOT NULL DEFAULT 'both' COMMENT 'wholesale, dropshipping, or both',
  `shop_id` int(11) NOT NULL DEFAULT 1,
  `category_id` bigint(20) unsigned NOT NULL,
  `brand_id` bigint(20) unsigned DEFAULT NULL,
  `subcategory_id` bigint(20) unsigned DEFAULT NULL,
  `minicategory_id` bigint(20) DEFAULT NULL,
  `bulk_status` varchar(255) DEFAULT NULL,
  `dorpshoping_status` varchar(255) DEFAULT NULL,
  `color` text DEFAULT NULL,
  `size` text DEFAULT NULL,
  `weight` text DEFAULT NULL,
  `ProductName` varchar(255) NOT NULL,
  `ProductSlug` varchar(255) NOT NULL,
  `ProductBreaf` longtext DEFAULT NULL,
  `ProductDetails` longtext DEFAULT NULL,
  `ProductSku` varchar(255) NOT NULL,
  `ProductWholesalePrice` decimal(10,2) NOT NULL DEFAULT 0.00,
  `ProductResellerPrice` decimal(10,2) NOT NULL DEFAULT 0.00,
  `min_sell_price` decimal(10,2) NOT NULL DEFAULT 0.00,
  `ProductRegularPrice` decimal(10,2) NOT NULL DEFAULT 0.00,
  `ProductSalePrice` decimal(10,2) NOT NULL DEFAULT 0.00,
  `Discount` varchar(255) NOT NULL DEFAULT '0',
  `ProductImage` varchar(255) NOT NULL DEFAULT 'public/images/product/default.jpg',
  `ViewProductImage` varchar(255) NOT NULL DEFAULT 'public/images/product/default.jpg',
  `PostImage` longtext DEFAULT NULL,
  `youtube_link` varchar(255) DEFAULT NULL,
  `MetaTitle` varchar(255) DEFAULT NULL,
  `MetaKey` varchar(255) DEFAULT NULL,
  `MetaDescription` text DEFAULT NULL,
  `meta_image` text DEFAULT NULL,
  `product_weight` decimal(10,2) NOT NULL DEFAULT 0.00,
  `minimum_qty` int(11) NOT NULL DEFAULT 1,
  `qty` int(11) NOT NULL DEFAULT 0,
  `low_stock` int(11) NOT NULL DEFAULT 0,
  `show_stock` varchar(255) NOT NULL DEFAULT 'Off',
  `show_stock_text` varchar(255) NOT NULL DEFAULT 'Off',
  `show_new_product` varchar(255) NOT NULL DEFAULT 'Off',
  `shipping_days` varchar(255) DEFAULT NULL,
  `ex_pack` decimal(10,2) NOT NULL DEFAULT 0.00,
  `ex_dvc` decimal(10,2) NOT NULL DEFAULT 0.00,
  `mart_status` varchar(255) NOT NULL DEFAULT 'Off',
  `reseller_status` varchar(255) NOT NULL DEFAULT 'Off',
  `reseller_bonus` decimal(10,2) NOT NULL DEFAULT 0.00,
  `status` varchar(255) NOT NULL DEFAULT 'Active',
  `event` tinyint(4) NOT NULL DEFAULT 1,
  `frature` tinyint(4) NOT NULL DEFAULT 0,
  `top_rated` tinyint(4) NOT NULL DEFAULT 0,
  `hot_list` varchar(255) NOT NULL DEFAULT 'Off',
  `ready_bost` varchar(255) NOT NULL DEFAULT 'Off',
  `profitable` varchar(255) NOT NULL DEFAULT 'Off',
  `limited` varchar(255) NOT NULL DEFAULT 'Off',
  `summer` varchar(255) NOT NULL DEFAULT 'Off',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `products_category_id_foreign` (`category_id`),
  KEY `products_subcategory_id_foreign` (`subcategory_id`),
  KEY `products_vendor_id_index` (`vendor_id`),
  KEY `products_vendor_approval_status_index` (`vendor_approval_status`),
  CONSTRAINT `products_category_id_foreign` FOREIGN KEY (`category_id`) REFERENCES `categories` (`id`) ON DELETE CASCADE,
  CONSTRAINT `products_subcategory_id_foreign` FOREIGN KEY (`subcategory_id`) REFERENCES `subcategories` (`id`) ON DELETE CASCADE,
  CONSTRAINT `products_vendor_id_foreign` FOREIGN KEY (`vendor_id`) REFERENCES `vendors` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=366 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

